def find(search_list, value):
    """Perform binary search on a sorted list and return the index of value.

    Raises ValueError("value not in array") if value is not present.
    """
    low = 0
    high = len(search_list) - 1

    while low <= high:
        mid = (low + high) // 2
        mid_val = search_list[mid]

        if mid_val == value:
            return mid
        if mid_val < value:
            low = mid + 1
        else:
            high = mid - 1

    raise ValueError("value not in array")
